package com.rekluzlabs.makokolorize.ui.screensimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.heightimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.layout.widthimport androidx.compose.foundation.rememberScrollStateimport androidx.compose.foundation.verticalScrollimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Infoimport androidx.compose.material3.AlertDialogimport androidx.compose.material3.Buttonimport androidx.compose.material3.ExperimentalMaterial3Apiimport androidx.compose.material3.FilterChipimport androidx.compose.material3.FilterChipDefaultsimport androidx.compose.material3.Iconimport androidx.compose.material3.IconButtonimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.ModalBottomSheetimport androidx.compose.material3.Sliderimport androidx.compose.material3.SliderDefaultsimport androidx.compose.material3.Textimport androidx.compose.material3.TextButtonimport androidx.compose.material3.rememberModalBottomSheetStateimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableFloatStateOfimport androidx.compose.runtime.mutableIntStateOfimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.alphaimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport com.rekluzlabs.makokolorize.domain.RunConfig@OptIn(ExperimentalMaterial3Api::class)@Composablefun PreflightSheet(    initialConfig: RunConfig,    onDismiss: () -> Unit,    onStart: (RunConfig) -> Unit,) {    val sheetState = rememberModalBottomSheetState(skipPartiallyExpanded = true)    var ddcolorInputSize by remember { mutableIntStateOf(initialConfig.ddcolorInputSize) }    var vibrancy by remember { mutableFloatStateOf(initialConfig.vibrancy) }    var upscalingEnabled by remember { mutableStateOf(initialConfig.upscalingEnabled) }    var faceRestoreEnabled by remember { mutableStateOf(initialConfig.faceRestoreEnabled) }    var denoisingEnabled by remember { mutableStateOf(initialConfig.denoisingEnabled) }    var codeFormerFidelity by remember { mutableFloatStateOf(initialConfig.codeFormerFidelity) }    var scunetStrength by remember { mutableFloatStateOf(initialConfig.scunetStrength) }    var scunetAdvancedNoiseRemoval by remember { mutableStateOf(initialConfig.scunetAdvancedNoiseRemoval) }    var showSizeInfo by remember { mutableStateOf(value = false) }    val anrAvailable = denoisingEnabled && (scunetStrength >= 0.10f)    ModalBottomSheet(        onDismissRequest = onDismiss,        sheetState = sheetState,    ) {        Column(            modifier = Modifier                .fillMaxWidth()                .padding(horizontal = 24.dp, vertical = 8.dp)                .verticalScroll(rememberScrollState()),            verticalArrangement = Arrangement.spacedBy(16.dp)        ) {            Text(                text = "Pre-flight Settings",                fontSize = 20.sp,                fontWeight = FontWeight.Bold,                modifier = Modifier.align(Alignment.CenterHorizontally)            )            // DDColor input size            val sizeLabel = when (ddcolorInputSize) {                512 -> "Fast"                768 -> "Balanced"                1024 -> "Detailed"                else -> ddcolorInputSize.toString()            }            Row(                verticalAlignment = Alignment.CenterVertically,                horizontalArrangement = Arrangement.spacedBy(4.dp)            ) {                Text(                    text = "DDColor Input Size: $sizeLabel (${ddcolorInputSize}px)",                    fontSize = 14.sp,                    fontWeight = FontWeight.Medium,                    color = MaterialTheme.colorScheme.onSurfaceVariant                )                IconButton(                    onClick = { showSizeInfo = true },                    modifier = Modifier.size(20.dp)                ) {                    Icon(                        imageVector = Icons.Default.Info,                        contentDescription = "Info",                        tint = MaterialTheme.colorScheme.primary,                        modifier = Modifier.size(16.dp)                    )                }            }            if (showSizeInfo) {                AlertDialog(                    onDismissRequest = { showSizeInfo = false },                    title = { Text("DDColor Input Size") },                    text = {                        Text("Before colorizing your photo, the AI resizes it to this resolution internally for analysis. A higher value means the AI sees finer detail when choosing colors, which improves accuracy for portraits and complex images. A lower value processes faster and uses less memory. Your final image is always saved at full resolution.\n\n⚠️ Higher values require significantly more memory and processing power. On older or lower-end devices, choosing 1024 may cause slower performance or the app to crash. If you experience issues, try a lower value.")                    },                    confirmButton = {                        TextButton(onClick = { showSizeInfo = false }) {                            Text("Got it")                        }                    }                )            }            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {                listOf(512, 768, 1024).forEach { size ->                    val chipLabel = when (size) {                        512 -> "Fast"                        768 -> "Balanced"                        1024 -> "Detailed"                        else -> size.toString()                    }                    FilterChip(                        selected = ddcolorInputSize == size,                        onClick = { ddcolorInputSize = size },                        label = { Text(chipLabel) }                    )                }            }            // Color vibrancy (moved from MainScreen)            Text(                text = "Color Vibrancy: ${"%.1f".format(vibrancy)}x",                fontSize = 14.sp,                fontWeight = FontWeight.Medium,                color = MaterialTheme.colorScheme.onSurfaceVariant            )            Row(verticalAlignment = Alignment.CenterVertically) {                Text("0.5x", fontSize = 12.sp, modifier = Modifier.width(28.dp))                Slider(                    value = vibrancy,                    onValueChange = { vibrancy = it },                    valueRange = 0.5f..2.0f,                    steps = 14,                    colors = SliderDefaults.colors(                        thumbColor = MaterialTheme.colorScheme.primary,                        activeTrackColor = MaterialTheme.colorScheme.primary                    ),                    modifier = Modifier.weight(1f)                )                Text("2.0x", fontSize = 12.sp, modifier = Modifier.width(28.dp))            }            // SCUNet denoising strength            Text(                text = "SCUNet Denoising Strength: ${"%.0f".format(scunetStrength * 100)}%",                fontSize = 14.sp,                fontWeight = FontWeight.Medium,                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(                    alpha = if (denoisingEnabled) 1f else 0.4f                )            )            Row(verticalAlignment = Alignment.CenterVertically) {                Text("0%", fontSize = 12.sp, modifier = Modifier.width(28.dp))                Slider(                    value = scunetStrength,                    onValueChange = {                        if (denoisingEnabled) {                            scunetStrength = it                            if (it < 0.10f) scunetAdvancedNoiseRemoval = false                        }                    },                    valueRange = 0f..1f,                    steps = 19,                    enabled = denoisingEnabled,                    colors = SliderDefaults.colors(                        thumbColor = MaterialTheme.colorScheme.primary,                        activeTrackColor = MaterialTheme.colorScheme.primary                    ),                    modifier = Modifier.weight(1f)                )                Text("100%", fontSize = 12.sp, modifier = Modifier.width(32.dp))            }            // Advanced noise removal toggle            Row(                horizontalArrangement = Arrangement.spacedBy(8.dp),                modifier = Modifier.alpha(if (anrAvailable) 1f else 0.4f)            ) {                FilterChip(                    selected = scunetAdvancedNoiseRemoval,                    onClick = { if (anrAvailable) scunetAdvancedNoiseRemoval = !scunetAdvancedNoiseRemoval },                    enabled = anrAvailable,                    label = { Text("Advanced Noise Removal") }                )            }            if (anrAvailable) {                Text(                    text = "Runs a second SCUNet pass for stronger denoising",                    fontSize = 11.sp,                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)                )            } else {                Text(                    text = if (scunetStrength < 0.10f) {                        "Increase denoising strength above 10% to enable"                    } else {                        "Enable Denoising pipeline toggle to use SCUNet"                    },                    fontSize = 11.sp,                    color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.4f)                )            }            Spacer(modifier = Modifier.height(8.dp))            // Pipeline toggles (disabled — not yet implemented)            Text(                text = "Pipeline",                fontSize = 14.sp,                fontWeight = FontWeight.Medium,                color = MaterialTheme.colorScheme.onSurfaceVariant            )            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {                FilterChip(                    selected = upscalingEnabled,                    onClick = { upscalingEnabled = !upscalingEnabled },                    enabled = false,                    label = { Text("Upscaling") }                )                FilterChip(                    selected = faceRestoreEnabled,                    onClick = { faceRestoreEnabled = !faceRestoreEnabled },                    enabled = false,                    label = { Text("Face Restore") }                )                FilterChip(                    selected = denoisingEnabled,                    onClick = { denoisingEnabled = !denoisingEnabled },                    enabled = true,                    label = { Text(if (denoisingEnabled) "Denoising ON" else "Denoising OFF") },                    colors = FilterChipDefaults.filterChipColors(                        containerColor = Color(0x66FF0000),                        labelColor = Color(0xFFFF4444),                        selectedContainerColor = Color(0x6600CC00),                        selectedLabelColor = Color(0xFF00CC00)                    )                )            }            Text(                text = "Pipeline: SCUNet denoising → DDColor colorization",                fontSize = 11.sp,                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.6f)            )            // CodeFormer fidelity (always visible, disabled)            Text(                text = "CodeFormer Fidelity: ${"%.2f".format(codeFormerFidelity)}",                fontSize = 14.sp,                fontWeight = FontWeight.Medium,                color = MaterialTheme.colorScheme.onSurfaceVariant.copy(alpha = 0.4f)            )            Row(verticalAlignment = Alignment.CenterVertically) {                Text("0.0", fontSize = 12.sp, modifier = Modifier.width(24.dp))                Slider(                    value = codeFormerFidelity,                    onValueChange = { },                    enabled = false,                    valueRange = 0f..1f,                    steps = 99,                    modifier = Modifier.weight(1f)                )                Text("1.0", fontSize = 12.sp, modifier = Modifier.width(24.dp))            }            // Estimated time hint            val estimate = "~${(ddcolorInputSize / 512) * 30}s on this device"            Text(                text = estimate,                fontSize = 12.sp,                color = MaterialTheme.colorScheme.onSurfaceVariant,                modifier = Modifier.align(Alignment.CenterHorizontally)            )            Spacer(modifier = Modifier.height(4.dp))            // Action buttons            Row(                modifier = Modifier.fillMaxWidth(),                horizontalArrangement = Arrangement.spacedBy(12.dp)            ) {                TextButton(                    onClick = onDismiss,                    modifier = Modifier.weight(1f)                ) {                    Text("Cancel")                }                Button(                    onClick = {                        onStart(                            RunConfig(                                ddcolorInputSize = ddcolorInputSize,                                vibrancy = vibrancy,                                upscalingEnabled = upscalingEnabled,                                faceRestoreEnabled = faceRestoreEnabled,                                denoisingEnabled = denoisingEnabled,                                codeFormerFidelity = codeFormerFidelity,                                scunetStrength = scunetStrength,                                scunetAdvancedNoiseRemoval = scunetAdvancedNoiseRemoval                            )                        )                    },                    modifier = Modifier.weight(1f)                ) {                    Text("Start Processing")                }            }            Spacer(modifier = Modifier.height(24.dp))        }    }}